import { untrack } from 'svelte';

export type LikeCommit = (liked: boolean, signal: AbortSignal) => Promise<unknown>;

export type OptimisticLikeOptions = {
	initialLiked?: boolean;
	initialCount?: number;
	onCommit?: LikeCommit;
	onError?: (error: unknown) => void;
	/** ms of quiet before the standing intent is sent */
	settle?: number;
};

export class OptimisticLikeState {
	#read: () => OptimisticLikeOptions;

	#liked = $state(false);
	#count = $state(0);
	#pending = $state(false);
	#burst = $state(0);
	#settled = $state<{ liked: boolean; count: number }>({ liked: false, count: 0 });

	// Mirrored outside the graph: a rapid tap reads back what the last tap wrote.
	#likedNow: boolean;
	#countNow: number;
	/** The last state the server agreed to — where a failed commit rolls back to. */
	#truth: { liked: boolean; count: number };

	#timer: ReturnType<typeof setTimeout> | undefined;
	#inFlight: AbortController | null = null;
	#seq = 0;

	constructor(options: OptimisticLikeOptions | (() => OptimisticLikeOptions) = {}) {
		this.#read = typeof options === 'function' ? options : () => options;

		const { initialLiked = false, initialCount = 0 } = untrack(this.#read);

		this.#liked = initialLiked;
		this.#count = initialCount;
		this.#settled = { liked: initialLiked, count: initialCount };
		this.#likedNow = initialLiked;
		this.#countNow = initialCount;
		this.#truth = { liked: initialLiked, count: initialCount };

		$effect(() => () => {
			clearTimeout(this.#timer);
			this.#timer = undefined;
			this.#seq += 1;
			this.#inFlight?.abort();
			this.#inFlight = null;
		});
	}

	get liked() {
		return this.#liked;
	}

	get count() {
		return this.#count;
	}

	/** The count with this like taken out of it, which is the other face of the readout. */
	get base() {
		return this.#liked ? this.#count - 1 : this.#count;
	}

	get pending() {
		return this.#pending;
	}

	/** Bumped on every like, so a view can key a burst off it. */
	get burst() {
		return this.#burst;
	}

	/** What the server agreed to. Safe to announce; the optimistic value is not. */
	get settled() {
		return this.#settled;
	}

	toggle = () => {
		const next = !this.#likedNow;
		this.#likedNow = next;
		this.#countNow += next ? 1 : -1;

		this.#liked = next;
		this.#count = this.#countNow;
		this.#pending = true;
		if (next) this.#burst += 1;

		clearTimeout(this.#timer);
		this.#timer = setTimeout(this.#flush, this.#read().settle ?? 400);
	};

	#flush = () => {
		this.#timer = undefined;
		this.#inFlight?.abort();
		this.#inFlight = null;
		this.#seq += 1;

		const intent = this.#likedNow;

		// Tapped back to where the server already is: nothing to send.
		if (intent === this.#truth.liked) {
			this.#countNow = this.#truth.count;
			this.#liked = this.#truth.liked;
			this.#count = this.#truth.count;
			this.#pending = false;
			return;
		}

		const target = { liked: intent, count: this.#countNow };
		const { onCommit, onError } = this.#read();

		if (!onCommit) {
			this.#truth = target;
			this.#settled = target;
			this.#pending = false;
			return;
		}

		const controller = new AbortController();
		const id = this.#seq;
		this.#inFlight = controller;
		this.#pending = true;

		onCommit(intent, controller.signal).then(
			() => {
				if (id !== this.#seq) return;
				this.#inFlight = null;
				this.#truth = target;
				this.#settled = target;
				this.#pending = false;
			},
			(error: unknown) => {
				if (id !== this.#seq) return;
				this.#inFlight = null;
				this.#likedNow = this.#truth.liked;
				this.#countNow = this.#truth.count;
				this.#liked = this.#truth.liked;
				this.#count = this.#truth.count;
				this.#pending = false;
				onError?.(error);
			}
		);
	};
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge class values, resolving Tailwind conflicts so the last one wins.
 *
 * This is what makes the `class` prop on every component behave the way the
 * registry documents it: "appended last to the root, so width and spacing are
 * the caller's". Plain concatenation would leave both `p-2` and the caller's
 * `p-4` in the list and let source order in the stylesheet decide; `twMerge`
 * drops the loser outright.
 *
 * Design-language classes from `layout.css` (`mat-panel`, `press`, `tnum`, …)
 * are not utilities, so `twMerge` passes them through untouched.
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
